/**
 * The shared contract for per-game modding support in Cyrus (PURE, client-safe, data + types only).
 * Every supported game has ONE file `lib/cyrus/games/<gameId>.ts` default-exporting a `GameSupport`.
 * The studio, the install flow, the lifecycle warnings, the mod store and the marketing page all read
 * from it, so a fact is written once. Facts must be VERIFIED against the loader's own docs/source
 * (cite the URL in `sources`), never guessed. Where something could not be confirmed, say so in `unknowns`.
 */

/** Where a mod's files must be installed for it to work. */
export type InstallSide = "server" | "client" | "both";

export type GameVersionRule = {
  /** Game/server build the mod targets, as the loader labels it ("1.21.4", "v0.4.x", "Build 42"). */
  version: string;
  status: "current" | "supported" | "legacy" | "unsupported";
  /** Loader/framework version needed with this game version ("BepInEx 5.4.2200", "Oxide 2.0.x"). */
  loaderVersion?: string;
  /** What changed that breaks mods from the previous version (so we can warn). */
  breaking?: string[];
};

export type DangerousApi = {
  /** Regex source matched against generated code; a hit blocks the build or forces a warning. */
  pattern: string;
  severity: "block" | "warn";
  why: string;
};

export type GameSupport = {
  id: string;                    // matches CyrusGame.id in lib/cyrus/games.ts
  name: string;
  /** Plain-language one-liner of what Cyrus builds for this game. */
  builds: string;
  /** Language(s) the mod is written in and the runtime that loads it. */
  language: "Java" | "C#" | "Lua" | "C++" | "JSON/data";
  loader: { name: string; homepage: string; installDocs: string; licenseNote?: string };
  versions: GameVersionRule[];
  /** Where it installs. `reason` is shown to the customer in plain words ("players must also install this"). */
  install: {
    side: InstallSide;
    serverPath: string;          // relative to the game server root
    clientNote?: string;         // what a player must do on their own PC, if side is client/both
    needsRestart: boolean;
    hotReload: boolean;
    packaging: "jar" | "cs-source" | "dll" | "zip" | "lua-folder" | "pak";
    reason: string;
  };
  /** How Cyrus verifies output BEFORE the customer sees it. */
  verification: {
    method: "compile" | "static-lint" | "load-test" | "none";
    notes: string;
    /** Can we run it for real in a sandbox here, or only lint? Be honest. */
    canRunSandbox: boolean;
  };
  dangerousApis: DangerousApi[];
  /** Things that commonly break players' games/servers for this title, with how we avoid them. */
  breakageRisks: { risk: string; guard: string }[];
  /** How a mod becomes "out of date": what signal tells us (game patch, loader update, API removal). */
  outdatedSignals: { signal: string; source: string }[];
  /** Mod categories this game's engine can actually express (ids from lib/cyrus/categories.ts universal set). */
  categories: string[];
  /** Concrete example prompts that work well, for the starter chips. */
  examplePrompts: string[];
  sources: string[];             // URLs verified while writing this file
  unknowns: string[];            // honest list of anything not confirmed
};

/**
 * The template toolkit shared by every game's code generator: the indentation-aware `code` tag,
 * seeded numbers, mod naming, effects parsed from the prompt and the feature list.
 */
import type { CategoryKey, CategoryMeta, CodeLanguage, Game, ModelId, ModFile } from "@/lib/cyrus/types";

export interface TemplateInput {
  game: Game;
  category: CategoryMeta;
  modName: string;
  prompt: string;
  model: ModelId;
  version: number;
}

/* ───────────── utilities ───────────── */

const EMPTY = "\u0000";

/**
 * Indentation-aware template tag: strips the common indent, re-indents multi-line
 * interpolations to the placeholder's column and drops lines whose only content was
 * an empty interpolation.
 */
export function code(strings: TemplateStringsArray, ...vals: unknown[]): string {
  let out = "";
  strings.forEach((s, i) => {
    out += s;
    if (i >= vals.length) return;
    const v = vals[i];
    let str = Array.isArray(v)
      ? v.filter((x) => x !== false && x != null && x !== "").map((x) => String(x).replace(/\n+$/, "")).join("\n")
      : v === false || v == null || v === ""
        ? ""
        : String(v).replace(/\n+$/, "");
    if (!str) str = EMPTY;
    const lineStart = out.slice(out.lastIndexOf("\n") + 1);
    const indent = lineStart.match(/^[ \t]*/)![0];
    out += str
      .split("\n")
      .map((l, j) => (j === 0 || !l ? l : indent + l))
      .join("\n");
  });
  const lines = out
    .replace(/^\n/, "")
    .split("\n")
    .filter((l) => l.trim() !== EMPTY)
    .map((l) => l.replaceAll(EMPTY, ""));
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
  const min = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)![0].length));
  return (
    lines
      .map((l) => l.slice(Number.isFinite(min) ? min : 0).trimEnd())
      .join("\n")
      .replace(/\n{3,}/g, "\n\n") + "\n"
  );
}

export function hashStr(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

export function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function languageForPath(path: string): CodeLanguage {
  const ext = path.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "java":
      return "java";
    case "psc":
      return "papyrus";
    case "cs":
      return "csharp";
    case "lua":
      return "lua";
    case "glsl":
    case "fsh":
    case "vsh":
    case "fx":
      return "glsl";
    case "json":
      return "json";
    case "md":
      return "markdown";
    case "xml":
      return "xml";
    case "toml":
    case "properties":
    case "txt":
      return ext === "txt" ? "text" : "toml";
    default:
      return "text";
  }
}

export const file = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/* ───────────── identity & numbers ───────────── */

export function identity(modName: string) {
  const words = modName.replace(/[^A-Za-z0-9 ]+/g, " ").split(/\s+/).filter(Boolean);
  let cls = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  if (!cls) cls = "AstralMod";
  if (/^\d/.test(cls)) cls = `Cy${cls}`;
  const snake = words.join("_").toLowerCase() || "astral_mod";
  return { cls, snake: /^\d/.test(snake) ? `cy_${snake}` : snake, kebab: snake.replace(/_/g, "-") };
}

export function numbers(input: TemplateInput) {
  const rnd = mulberry32(hashStr(`${input.game.id}|${input.category.key}|${input.modName}|${input.version}`));
  const r = (a: number, b: number, d = 1) => Number((a + rnd() * (b - a)).toFixed(d));
  const i = (a: number, b: number) => Math.round(a + rnd() * (b - a));
  return {
    power: r(5, 14),
    cooldown: r(1.5, 8),
    radius: i(3, 9),
    duration: i(4, 12),
    chance: r(0.12, 0.4, 2),
    health: i(18, 90) * 10,
    speed: r(0.24, 0.42, 2),
    interval: i(2, 10),
    xp: i(12, 80),
    hue: i(0, 359),
    intensity: r(0.6, 1.4, 2),
    rnd,
  };
}

/* ───────────── intent: effects parsed from the prompt ───────────── */

