export function planThinking(input: TemplateInput, files: ModFile[], refining: boolean): ThinkStep[] {
  const { game, category, model, prompt, version } = input;
  const features = deriveFeatures(input);
  const short = prompt.length > 54 ? `${prompt.slice(0, 54).trim()}…` : prompt;
  const steps: ThinkStep[] = [
    { label: refining ? "Reading the current build" : "Parsing intent", detail: `“${short}” → ${features.length} mechanics`, ms: 700 },
    { label: "Routing through the core", detail: `Cyrus Core › ${game.name} › ${category.label}`, ms: 650 },
  ];
  if (model !== "katara") {
    steps.push({ label: `Mapping ${game.short} API surface`, detail: API_SURFACE[game.id] ?? `${game.toolchain} · events · content hooks`, ms: 800 });
    steps.push({ label: "Designing mechanics", detail: features.slice(0, 2).join(" · "), ms: 850 });
  }
  if (model === "yakko") {
    steps.push({ label: "Exploring alternatives", detail: "3 architectures considered → event-driven wins", ms: 1000 });
    steps.push({ label: "Stress-testing edge cases", detail: "multiplayer sync · save/load · mod conflicts", ms: 950 });
    steps.push({ label: "Balancing numbers", detail: "simulated 400 encounters against vanilla curves", ms: 900 });
  }
  steps.push({ label: `Scaffolding ${files.length} files`, detail: `${game.toolchain} · v${version}`, ms: 600 });
  return steps;
}

/* ───────────── Versions & diffs ───────────── */

export function diffStats(prev: ModFile[] | undefined, next: ModFile[]) {
  const count = (files: ModFile[]) => {
    const m = new Map<string, number>();
    for (const f of files) for (const line of f.content.split("\n")) if (line.trim()) m.set(line, (m.get(line) ?? 0) + 1);
    return m;
  };
  const a = count(prev ?? []);
  const b = count(next);
  let additions = 0;
  let deletions = 0;
  for (const [line, n] of b) additions += Math.max(0, n - (a.get(line) ?? 0));
  for (const [line, n] of a) deletions += Math.max(0, n - (b.get(line) ?? 0));
  return { additions, deletions };
}

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

