    logic: code`
      private class StoredData
      {
          public Dictionary<ulong, List<RaidEntry>> Logs = new Dictionary<ulong, List<RaidEntry>>();
      }

      private class RaidEntry
      {
          public string Attacker, Target, Grid, Weapon;
          public ulong AttackerId;
          public DateTime When;
      }

      private void Alert(BuildingPrivlidge priv, BaseCombatEntity entity, BasePlayer attacker, HitInfo info)
      {
          float last;
          var now = Time.realtimeSinceStartup;
          if (lastAlert.TryGetValue(priv.net.ID.Value, out last) && now - last < config.AlertCooldown) return;
          lastAlert[priv.net.ID.Value] = now;

          var grid = PhoneController.PositionToGridName(entity.transform.position);
          var weapon = info.WeaponPrefab != null ? info.WeaponPrefab.ShortPrefabName : info.Weapon?.GetItem()?.info.shortname ?? "unknown";
          var entry = new RaidEntry { Attacker = attacker.displayName, AttackerId = attacker.userID.Get(), Target = entity.ShortPrefabName, Grid = grid, Weapon = weapon, When = DateTime.UtcNow };
          foreach (var member in OnlineTeam(entity.OwnerID))
          {
              Reply(member, "RaidAlert", attacker.displayName, entity.ShortPrefabName, grid, weapon);
              EffectNetwork.Send(new Effect(FxAlarm, member, 0, Vector3.zero, Vector3.zero), member.net.connection);
              if (Vector3.Distance(member.transform.position, entity.transform.position) < config.RaidBlockRadius) raidBlocked[member.userID.Get()] = now + config.RaidBlockSeconds;
              List<RaidEntry> log;
              if (!data.Logs.TryGetValue(member.userID.Get(), out log)) data.Logs[member.userID.Get()] = log = new List<RaidEntry>();
              log.Insert(0, entry);
              if (log.Count > config.LogSize) log.RemoveRange(config.LogSize, log.Count - config.LogSize);
          }
          LogToFile("raids", $"{attacker.displayName} [{attacker.UserIDString}] hit {entity.ShortPrefabName} owned by {entity.OwnerID} at {grid} with {weapon}", this);
          ${deep ? `Interface.CallHook("On${cls}Alert", priv, attacker, grid);` : ""}
      }

      private IEnumerable<BasePlayer> OnlineTeam(ulong ownerId)
      {
          var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
          foreach (var id in team != null ? team.members : new List<ulong> { ownerId })
          {
              var member = BasePlayer.FindByID(id);
              if (member != null && permission.UserHasPermission(member.UserIDString, PermUse)) yield return member;
          }
      }

      private object RaidBlocked(BasePlayer player)
      {
          float until;
          if (player == null || !raidBlocked.TryGetValue(player.userID.Get(), out until) || until < Time.realtimeSinceStartup) return null;
          Reply(player, "RaidBlocked", until - Time.realtimeSinceStartup);
          return false;
      }`,
