  /* ───── assembly: effects, helpers, consts, config entries and messages are emitted only when referenced ───── */
  const own = join(m.hooks, m.commands, m.logic, ...(m.start ?? []));
  const fx = /\bApplyEffects\(/.test(own) ? fxs.map((e) => FX[e.key]) : [];
  const applies = fx.map((f) => f.apply).join("\n\n");
  const locals = [["caster", "attacker as BasePlayer"], ["victim", "target as BasePlayer"], ["pos", "(target ?? attacker).transform.position"]].filter(([v]) => new RegExp(`\\b${v}\\b`).test(applies));
  const effects =
    fx.length > 0 &&
    join(
      block("private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)", [
        "if (applying || (attacker == null && target == null)) return;",
        "applying = true;",
        block("try", [[locals.map(([v, e]) => `var ${v} = ${e};`).join("\n"), applies.replace(/\n+$/, "")].filter(Boolean).join("\n\n")]),
        block("finally", ["applying = false;"]),
      ]),
      ...fx.map((f) => f.member).filter((s) => s && !own.includes(s.match(/void (\w+\()/)![1])),
    );
  const helpers: [RegExp, string | undefined, string][] = [
    [/\bOnCooldown\(/, "private readonly Dictionary<ulong, float> cooldowns = new Dictionary<ulong, float>();", code`
      private bool OnCooldown(BasePlayer player, bool notify = false)
      {
          float readyAt;
          var now = Time.realtimeSinceStartup;
          if (cooldowns.TryGetValue(player.userID.Get(), out readyAt) && readyAt > now)
          {
              if (notify) Reply(player, "Cooldown", readyAt - now);
              return true;
          }
          cooldowns[player.userID.Get()] = now + config.Cooldown;
          return false;
      }`],
    [/\bsummonOwners\b/, "private readonly Dictionary<ulong, ulong> summonOwners = new Dictionary<ulong, ulong>();", code`
      // Keeps owned NPCs off their owner and the owner's allies.
      private object OnNpcTarget(BaseEntity npc, BaseEntity target)
      {
          ulong ownerId;
          var player = target as BasePlayer;
          if (npc?.net == null || player == null || !summonOwners.TryGetValue(npc.net.ID.Value, out ownerId)) return null;
          return player.userID.Get() == ownerId || IsAlly(BasePlayer.FindByID(ownerId), player) ? true : (object)null;
      }`],
    [/\bIsAlly\(/, deep ? "[PluginReference] private Plugin Clans, Friends;" : undefined, !deep ? "private static bool IsAlly(BasePlayer a, BasePlayer b) => a != null && b != null && (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam));" : code`
      private bool IsAlly(BasePlayer a, BasePlayer b)
      {
          if (a == null || b == null) return false;
          if (a == b || (a.currentTeam != 0UL && a.currentTeam == b.currentTeam)) return true;
          if (Friends != null && Friends.Call<bool>("AreFriends", a.UserIDString, b.UserIDString)) return true;
          return Clans != null && Clans.Call<bool>("IsClanMember", a.UserIDString, b.UserIDString);
      }`],
    [/\bIsTeammate\(/, undefined, code`
      private static bool IsTeammate(ulong ownerId, BasePlayer player)
      {
          var team = RelationshipManager.ServerInstance.FindPlayersTeam(ownerId);
          return player != null && team != null && team.members.Contains(player.userID.Get());
      }`],
    [/\bDamage\(/, undefined, code`
      private static void Damage(BaseCombatEntity target, BaseEntity attacker, HitInfo info, DamageType type, float amount)
      {
          if (info != null) info.damageTypes.Add(type, amount);
          else target.Hurt(amount, type, attacker);
      }`],
    [/\bReply\(/, undefined, 'private void Reply(BasePlayer player, string key, params object[] args) => SendReply(player, $"{config.ChatPrefix} {Lang(key, player.UserIDString, args)}");'],
    [/\bBroadcast\(/, undefined, 'private void Broadcast(string key, params object[] args) => PrintToChat($"{config.ChatPrefix} {Lang(key, null, args)}");'],
    [/./, undefined, "private string Lang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);"],
  ];
  const api = input.model !== "katara" ? m.api : "";
  let scan = join(own, effects, api, ...(m.init ?? []), ...(m.unload ?? []));
  const used = new Set<number>();
  for (let pass = 0; pass < 3; pass++) helpers.forEach(([re, , body], i) => !used.has(i) && re.test(scan) && (used.add(i), (scan += "\n" + body)));
  const helperList = helpers.filter((_, i) => used.has(i));
  const uis = [...new Set(scan.match(/\bUi[A-Z]\w*/g) ?? [])];
  const admin = /\bPermAdmin\b/.test(scan);
  const use = /\bPermUse\b/.test(scan);
  const fields = [
    use && `private const string PermUse = "${lc}.use";`,
    admin && `private const string PermAdmin = "${lc}.admin";`,
