// Cyrus mod categories: the middle branch of the web (Cyrus core -> game -> category -> mod).
// Deterministic keyword classifier over the build's own words (title, plugin name, tagline,
// summary, prompt); anything unmatched falls back to "Other". Pure, tested in test/cyrus.test.ts.

export type CyrusCategoryId = "worldgen" | "biomes" | "structures" | "gameplay" | "visuals" | "utility" | "other";

export type CyrusCategory = { id: CyrusCategoryId; name: string; icon: string; hue: string; words: RegExp };

/** Order = order on the web (left to right around the live game). Hues are the branch colours. */
export const CYRUS_CATEGORIES: CyrusCategory[] = [
  { id: "worldgen", name: "World Generation", icon: "tree", hue: "#3cf0c8", words: /\b(world ?gen|terrain|ores?|dimension|caves?|generat\w*|islands?|continents?|seed|mountains?|drops?|loot)\b/i },
  { id: "biomes", name: "Biomes", icon: "flower", hue: "#d94aff", words: /\b(biomes?|forests?|deserts?|jungle|swamp|weather|seasons?|flora|fauna|animals?|mobs?)\b/i },
  { id: "structures", name: "Structures", icon: "pickaxe", hue: "#2f7bff", words: /\b(structures?|villages?|dungeons?|towers?|castles?|houses?|buildings?|arenas?|zones?|regions?|claims?|protect\w*|grief)\b/i },
  { id: "gameplay", name: "Gameplay", icon: "gamecube", hue: "#ff3fd8", words: /\b(game|mini-?game|quests?|boss\w*|economy|coins?|shop|pay|pvp|combat|spleef|rewards?|streaks?|levels?|skills?|parkour|kits?|duels?)\b/i },
  { id: "visuals", name: "Visuals", icon: "visuals", hue: "#a42bff", words: /\b(scoreboards?|sidebar|particles?|titles?|hud|cosmetics?|colou?rs?|holograms?|tab ?list|nametags?|chat format|welcome|join messages?|display)\b/i },
  { id: "utility", name: "Utility", icon: "wrench", hue: "#2ee0f5", words: /\b(commands?|homes?|spawn|teleport\w*|tpa|heal|feed|admin|tools?|backpacks?|warps?|chat|messages?|msg|mute|permissions?|utility)\b/i },
  { id: "other", name: "Other", icon: "cube", hue: "#7a6bff", words: /$^/ },
];

export const cyrusCategory = (id: string) => CYRUS_CATEGORIES.find((c) => c.id === id) ?? CYRUS_CATEGORIES[CYRUS_CATEGORIES.length - 1];

/** Pick the category whose words appear most in the text (title words count double). */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  const title = parts.title || "";
  const text = parts.text || "";
  let best: CyrusCategoryId = "other", score = 0;
  for (const c of CYRUS_CATEGORIES) {
    if (c.id === "other") continue;
    const g = new RegExp(c.words.source, "gi");
    const n = (title.match(g)?.length ?? 0) * 2 + (text.match(g)?.length ?? 0);
    if (n > score) { score = n; best = c.id; }
  }
  return best;
}

/** Template category -> web category (templates fill empty branches, clearly marked). */
export const TEMPLATE_CATEGORY: Record<string, CyrusCategoryId> = { Gameplay: "gameplay", Economy: "gameplay", Social: "visuals", Admin: "utility", World: "worldgen" };

