/**
 * Rust (Facepunch) modding support for Cyrus. PURE, client-safe data. Verified 2026-10-08 against the loaders'
 * own sources (Oxide.Rust/Oxide.Core/Oxide.CSharp on GitHub, Oxide's Rust.opj patch manifest, Carbon's published
 * hook/prefab/item index and docs) and Facepunch's community server guidelines. Every URL is in `sources`.
 *
 * Model of the platform in one paragraph: a Rust "mod" is a server plugin, a single C# source file (`.cs`) that
 * Oxide (uMod) or Carbon compiles on the server when it appears in the plugins folder and hot-reloads when it
 * changes. Players install nothing: Rust has no client modding (the client is protected by Easy Anti-Cheat) and
 * plugin UI (CUI) is drawn by the server. Facepunch ships a forced update on the first Thursday of every month;
 * the framework must be updated the same day and plugins that touched changed game code stop compiling.
 */
import type { GameSupport, GameVersionRule } from "./support";

/** Monthly update table, newest first. Update it on every first-Thursday forced wipe (see READINESS.md). */
export const RUST_VERSIONS: GameVersionRule[] = [
  {
    version: "2026-10",
    status: "current",
    loaderVersion: "Oxide 2.0.7783+ (latest 2.0.7815) or Carbon production 2.0.262+",
    breaking: [
      "Monthly forced update of 1 October 2026: new server assemblies and network protocol. Servers on the September build cannot be joined.",
      "Oxide ships pre-patched game DLLs, so Oxide must be updated the same day (2.0.7783 was released for this update on 1 Oct 2026).",
    ],
  },
  {
    version: "2026-09",
    status: "unsupported",
    loaderVersion: "Oxide 2.0.7676 - 2.0.7726",
    breaking: ["Superseded by the October forced update. Clients on the current build cannot connect to a September server."],
  },
];

/** The next forced update (first Thursday of the month, 18:00 UTC in British Summer Time, 19:00 UTC otherwise). */
export function nextRustForcedUpdate(from: Date = new Date()): Date {
  for (let i = 0; i < 3; i++) {
    const y = from.getUTCFullYear();
    const m = from.getUTCMonth() + i;
    const first = new Date(Date.UTC(y, m, 1));
    const day = 1 + ((4 - first.getUTCDay() + 7) % 7); // Thursday = 4
    const month = first.getUTCMonth();
    // BST runs from the last Sunday of March to the last Sunday of October; a first Thursday is never near either edge
    // except early April / early November, so month alone decides it.
    const hour = month >= 3 && month <= 9 ? 18 : 19;
    const at = new Date(Date.UTC(first.getUTCFullYear(), month, day, hour));
    if (at.getTime() > from.getTime()) return at;
  }
  return from;
}

export const RUST_CURRENT_VERSION = RUST_VERSIONS.find((v) => v.status === "current")!.version;

/** Folders on a Nxeon Rust server (root /opt/rust, see lib/game-files-roots.ts). Carbon is not offered yet. */
export const RUST_PATHS = {
  oxide: { plugins: "oxide/plugins", config: "oxide/config", data: "oxide/data", lang: "oxide/lang/en", logs: "oxide/logs" },
  carbon: { plugins: "carbon/plugins", config: "carbon/configs", data: "carbon/data", lang: "carbon/lang/en", logs: "carbon/logs" },
} as const;

const rust: GameSupport = {
  id: "rust",
  name: "Rust",
  builds:
    "Server plugins for Oxide (uMod) and Carbon, written in C#: custom items, events, raid tools, HUDs, gather rates and admin tools. Your players don't install anything.",
  language: "C#",
  loader: {
    name: "Oxide (uMod) / Carbon",
    homepage: "https://umod.org/games/rust",
    installDocs: "https://docs.carbonmod.gg/owners/oxide-porting",
    licenseNote:
      "Oxide is MIT-licensed open source (github.com/OxideMod). Carbon is free and runs Oxide plugins unchanged, but Oxide and Carbon can never be installed on the same server.",
  },
  versions: RUST_VERSIONS,
  install: {
    side: "server",
    serverPath: RUST_PATHS.oxide.plugins,
    clientNote:
      "Nothing to install on your players' computers. Rust doesn't allow client mods, and everything a plugin shows (menus, HUDs, messages) is sent by your server.",
    needsRestart: false,
    hotReload: true,
    packaging: "cs-source",
    reason:
      "Rust plugins run only on your server. Drop the .cs file into oxide/plugins and Oxide compiles and loads it within a few seconds, no restart needed. Its settings appear in oxide/config the first time it loads.",
  },
  verification: {
