input.content:
/**
 * Static validation for Rust (Oxide/Carbon) plugins, run on every generated or edited project BEFORE the customer
 * sees it or it reaches a server. PURE (no fs, no network): input is the project's files, output is findings.
 *
 * Why this matters on Rust specifically: Oxide compiles `.cs` source on the server with full process rights (there is
 * no plugin sandbox in Oxide.CSharp), so this check is the safety gate. It enforces:
 *   1. structure Oxide needs (namespace, [Info] with a semantic version, a RustPlugin class named like its file),
 *   2. the Cyrus manifest (cyrus.mod.json) with the target game build, side and entry,
 *   3. the GameSupport `dangerousApis` (block/warn) and the version knowledge `failureRules`,
 *   4. hygiene that keeps servers healthy: hooks that really exist, prefixed permissions, data kept in the
 *      plugin's own folder, cleanup in Unload() when the plugin spawns entities or UI.
 */
import rust, { RUST_VERSIONS } from "./rust";
import { RUST_HOOK_NAMES } from "./rust.hooks";

export type RustSeverity = "block" | "warn" | "info";
export interface RustFinding {
  rule: string;
  severity: RustSeverity;
  message: string;
  file?: string;
  line?: number;
}
export interface RustValidation {
  ok: boolean;
  findings: RustFinding[];
  /** The plugin entry file and class, when found. */
  entry?: { path: string; className: string; title: string; version: string };
}
type SourceFile = { path: string; content: string };

const SEMVER = /^\d+\.\d+\.\d+$/;
const PLUGIN_BASES = /\b(RustPlugin|CovalencePlugin|CarbonPlugin)\b/;
/** Hook-shaped names Oxide calls on the plugin itself (overrides), never reported as unknown hooks. */
const FRAMEWORK_METHODS = new Set(["LoadConfig", "SaveConfig", "LoadDefaultConfig", "LoadDefaultMessages"]);

/**
 * Removes comments and (optionally) blanks string contents, keeping offsets/lines stable so findings can point at a line.
 * Handles "..." with escapes, verbatim @"..." ("" escapes), $"..." (treated like a normal string) and char literals.
 */
export function stripCSharp(src: string, blankStrings = false): string {
  let out = "";
  let i = 0;
  const keep = (s: string) => (out += s);
  const blank = (s: string) => (out += s.replace(/[^\n]/g, " "));
  while (i < src.length) {
    const c = src[i];
    const n = src[i + 1];
    if (c === "/" && n === "/") {
      const end = src.indexOf("\n", i);
      const stop = end < 0 ? src.length : end;
      blank(src.slice(i, stop));
      i = stop;
    } else if (c === "/" && n === "*") {
      const end = src.indexOf("*/", i + 2);
      const stop = end < 0 ? src.length : end + 2;
      blank(src.slice(i, stop));
      i = stop;
    } else if (c === '"' || ((c === "@" || c === "$") && (n === '"' || ((n === "@" || n === "$") && src[i + 2] === '"')))) {
      const prefixLen = c === '"' ? 0 : n === '"' ? 1 : 2;
      const verbatim = src.slice(i, i + prefixLen).includes("@");
      let j = i + prefixLen + 1;
      while (j < src.length) {
        if (verbatim && src[j] === '"' && src[j + 1] === '"') { j += 2; continue; }
        if (!verbatim && src[j] === "\\") { j += 2; continue; }
        if (src[j] === '"') break;
        if (!verbatim && src[j] === "\n") break;
        j++;
      }
      const lit = src.slice(i, j + 1);
      if (blankStrings) { keep(src.slice(i, i + prefixLen + 1)); blank(lit.slice(prefixLen + 1, -1)); keep('"'); }
      else keep(lit);
      i = j + 1;
    } else if (c === "'") {
      let j = i + 1;
      while (j < src.length && src[j] !== "'" && src[j] !== "\n") j += src[j] === "\\" ? 2 : 1;
      const lit = src.slice(i, j + 1);
      if (blankStrings) { keep("'"); blank(lit.slice(1, -1)); keep("'"); } else keep(lit);
      i = j + 1;
    } else {
      keep(c);
      i++;
    }
  }
  return out;
}

const lineAt = (src: string, index: number) => src.slice(0, index).split("\n").length;

function balanced(code: string): string | null {
  const pairs: Record<string, string> = { "}": "{", ")": "(", "]": "[" };
  const stack: string[] = [];
  for (const ch of code) {
    if (ch === "{" || ch === "(" || ch === "[") stack.push(ch);
    else if (ch in pairs) {
      if (stack.pop() !== pairs[ch]) return `unexpected '${ch}'`;
    }
  }
  return stack.length ? `${stack.length} unclosed '${stack[stack.length - 1]}'` : null;
}

/** Validates ONE plugin source. Exported so the editor can lint a single file as the customer types. */
export function validateRustSource(path: string, content: string): { findings: RustFinding[]; entry?: RustValidation["entry"] } {
  const findings: RustFinding[] = [];
  const add = (rule: string, severity: RustSeverity, message: string, index?: number) =>
    findings.push({ rule, severity, message, file: path, line: index == null ? undefined : lineAt(content, index) });

  const code = stripCSharp(content); // comments gone, strings kept (some rules need string contents)
  const bare = stripCSharp(content, true); // comments and string contents gone

  const unbalanced = balanced(bare);
  if (unbalanced) add("syntax-braces", "block", `Brackets don't balance (${unbalanced}); the plugin will not compile.`);

  if (!/\bnamespace\s+(Oxide|Carbon)\.Plugins\b/.test(code)) add("structure-namespace", "block", "Plugins must be declared in `namespace Oxide.Plugins` (or Carbon.Plugins for Carbon-only plugins).");

  const info = /\[Info\(\s*"([^"]+)"\s*,\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\)\]/.exec(code);
  let title = "";
  let version = "";
  if (!info) add("structure-info", "block", 'Missing `[Info("Title", "Author", "1.0.0")]`; Oxide will not load the plugin without it.');
  else {
    [, title, , version] = info;
    if (!SEMVER.test(version)) add("version-format", "block", `[Info] version "${version}" must look like 1.2.3 so servers and the mod store can compare versions.`, info.index);
  }

  const cls = /\b(?:public\s+|internal\s+)?(?:sealed\s+|partial\s+)*class\s+(\w+)\s*:\s*([\w.]+)/.exec(bare);
  const fileClass = path.split("/").pop()!.replace(/\.cs$/, "");
  let className = "";
  if (!cls || !PLUGIN_BASES.test(cls[2])) add("structure-class", "block", "No plugin class found: expected `public class <Name> : RustPlugin`.");
  else {
    className = cls[1];
    if (className !== fileClass) add("structure-filename", "block", `Oxide requires the file name to match the class: rename ${fileClass}.cs to ${className}.cs.`, cls.index);
  }

  for (const d of rust.dangerousApis) {
    const re = new RegExp(d.pattern, "g");
    const hit = re.exec(code);
