      if (m.targetGameVersion && !target) findings.push({ rule: "version-unknown", severity: "warn", file: mf.path, message: `Target game build ${String(m.targetGameVersion)} is not in Cyrus's version table.` });
      else if (target && (target.status === "unsupported" || target.status === "legacy")) {
        findings.push({ rule: "version-outdated", severity: "warn", file: mf.path, message: `Built for Rust ${target.version}, which is no longer current. Re-check it against ${RUST_VERSIONS[0].version} before installing.` });
      }
      if (entry) {
        if (m.entry !== entry.path) findings.push({ rule: "manifest-entry", severity: "block", file: mf.path, message: `Manifest entry ${String(m.entry)} does not match the plugin file ${entry.path}.` });
        if (m.pluginClass !== entry.className) findings.push({ rule: "manifest-entry", severity: "block", file: mf.path, message: `Manifest pluginClass ${String(m.pluginClass)} does not match class ${entry.className}.` });
        if (m.version !== entry.version) findings.push({ rule: "manifest-version", severity: "warn", file: mf.path, message: `Manifest version ${String(m.version)} differs from [Info] version ${entry.version}.` });
      }
      const install = (m.install ?? {}) as Record<string, string>;
      for (const dest of Object.values(install)) {
        if (typeof dest !== "string" || dest.includes("..") || dest.startsWith("/") || !/^(oxide|carbon)\/(plugins|config|configs|data|lang)\//.test(dest)) {
          findings.push({ rule: "manifest-install", severity: "block", file: mf.path, message: `Install target "${String(dest)}" is outside the framework's plugins/config/data/lang folders.` });
        }
      }
    }
  }

  return { ok: !findings.some((f) => f.severity === "block"), findings, entry };
}

