// Cyrus · Rust (Oxide/Carbon): the verified GameSupport, the version-aware generator and the static validator.
// Pure: no DB, no network, no game files. Run with `tsx --test test/cyrus-game-rust.test.ts`.
import { describe, it } from "node:test";
import assert from "node:assert/strict";

import rust, { RUST_CURRENT_VERSION, RUST_VERSIONS, nextRustForcedUpdate } from "../lib/cyrus/games/rust.ts";
import { RUST_HOOK_NAMES } from "../lib/cyrus/games/rust.hooks.ts";
import { stripCSharp, validateRustProject, validateRustSource } from "../lib/cyrus/games/rust.validate.ts";
import { buildModFiles } from "../lib/cyrus/engine/templates.ts";
import { CATEGORIES, GAME_BY_ID } from "../lib/cyrus/data.ts";
import type { ModelId } from "../lib/cyrus/types.ts";

const RUST = GAME_BY_ID.rust;
const MODELS: ModelId[] = ["katara", "saka", "yakko"];
const PROMPTS = [
  "",
  "frost ak that slows whoever it hits",
  "fire staff that burns and teleports behind the target",
  "smart raid alarms that ping my team",
  "x3 gather rates for wood and stone",
  "personal minicopter with a boost",
  "mutant wolves that poison",
  "a scientist bodyguard companion that heals me",
  "monument event at night with a locked crate",
  "team hud with grid and health bars",
  "sound cues for hits and kills",
  "moonlit color grade with fog",
  "questline with scrap rewards",
  "lightning summon spear",
  "neon hacker pistol",
];

/** Every prefab Cyrus may emit, each checked against Carbon's prefab index for Rust 2634.289.1 on 2026-10-08. */
const VERIFIED_PREFABS = new Set([
  "assets/bundled/prefabs/fireball_small.prefab",
  "assets/bundled/prefabs/fx/explosions/explosion_03.prefab",
  "assets/bundled/prefabs/fx/gestures/drink_vomit.prefab",
  "assets/bundled/prefabs/fx/headshot.prefab",
  "assets/bundled/prefabs/fx/invite_notice.prefab",
  "assets/bundled/prefabs/fx/takedamage_hit.prefab",
  "assets/content/vehicles/bikes/motorbike.prefab",
  "assets/content/vehicles/boats/rhib/rhib.prefab",
  "assets/content/vehicles/boats/rowboat/rowboat.prefab",
  "assets/content/vehicles/minicopter/minicopter.entity.prefab",
  "assets/content/vehicles/modularcar/3module_car_spawned.entity.prefab",
  "assets/content/vehicles/scrap heli carrier/scraptransporthelicopter.prefab",
  "assets/content/vehicles/snowmobiles/snowmobile.prefab",
  "assets/content/vehicles/submarine/submarinesolo.entity.prefab",
  "assets/prefabs/deployable/chinooklockedcrate/codelockedhackablecrate.prefab",
  "assets/prefabs/deployable/research table/effects/research-success.prefab",
  "assets/prefabs/locks/keypad/effects/lock.code.shock.prefab",
  "assets/prefabs/misc/halloween/lootbag/effects/silver_open.prefab",
  "assets/prefabs/misc/xmas/presents/effects/unwrap.prefab",
  "assets/prefabs/npc/patrol helicopter/effects/rocket_fire.prefab",
  "assets/rust.ai/agents/bear/bear.prefab",
  "assets/rust.ai/agents/bear/polarbear.prefab",
  "assets/rust.ai/agents/boar/boar.prefab",
  "assets/rust.ai/agents/chicken/chicken.prefab",
  "assets/rust.ai/agents/fish/simpleshark.prefab",
  "assets/rust.ai/agents/stag/stag.prefab",
  "assets/rust.ai/agents/wolf/wolf2.prefab",
  "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_heavy.prefab",
  "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_peacekeeper.prefab",
  "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_roam.prefab",
]);
/** APIs we could not verify for 2634.289.1 (or know to be wrong); the generator must never emit them. */
const BANNED = [/BUTTON\.FIRE_THIRD/, /PositionToGridName/, /ApplyInheritedVelocity/, /SendChangesToClient/, /lifeTimeM(in|ax)/, /damageTypes\.Add\(/, /task\.owner/, /temperature\.SetValue/, /example\.com/, /Call<bool>/, /testridablehorse/, /agents\/wolf\/wolf\.prefab/];

function projects() {
  const out: { label: string; files: ReturnType<typeof buildModFiles> }[] = [];
  for (const category of CATEGORIES) {
    for (const model of MODELS) {
      for (const [i, prompt] of PROMPTS.entries()) {
        const modName = ["Frost Bite", "Raid Siren", "Night Shift", "Iron Mule", "Item"][i % 5];
        for (const version of [1, 2]) {
          out.push({ label: `${category.key}/${model}/${i}/v${version}`, files: buildModFiles({ game: RUST, category, modName, prompt: prompt || `${modName} for Rust`, model, version }) });
        }
      }
    }
  }
  return out;
}

describe("Rust GameSupport", () => {
  it("is a verified, server-only, hot-reloading C# source mod", () => {
    assert.equal(rust.id, "rust");
    assert.equal(rust.language, "C#");
    assert.equal(rust.install.side, "server");
    assert.equal(rust.install.packaging, "cs-source");
    assert.equal(rust.install.hotReload, true);
    assert.equal(rust.install.needsRestart, false);
    assert.equal(rust.install.serverPath, "oxide/plugins");
    assert.ok(rust.install.clientNote && /nothing to install/i.test(rust.install.clientNote));
    assert.equal(rust.verification.canRunSandbox, false, "no game-file sandbox yet; must stay honest");
    assert.ok(rust.sources.length >= 10 && rust.unknowns.length >= 3);
  });

  it("has exactly one current game build, and it is the one the generator targets", () => {
    assert.equal(RUST_VERSIONS.filter((v) => v.status === "current").length, 1);
    assert.equal(RUST_CURRENT_VERSION, RUST_VERSIONS[0].version);
    assert.match(RUST_CURRENT_VERSION, /^\d{4}\.\d{3}\.\d+$/);
    assert.equal(rust.knowledge?.version, RUST_CURRENT_VERSION);
  });

  it("every dangerous-API pattern and failure rule is a valid regex with a reason", () => {
    for (const d of rust.dangerousApis) {
      assert.doesNotThrow(() => new RegExp(d.pattern), d.pattern);
      assert.ok(d.why.length > 20);
    }
    for (const r of rust.knowledge!.failureRules) {
      assert.doesNotThrow(() => new RegExp(r.detect), r.id);
      assert.ok(r.fix && r.why, r.id);
    }
    assert.ok(rust.knowledge!.apiSheet.length >= 20);
  });

  it("only uses the universal category ids", () => {
    const universal = ["environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests", "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance"];
    for (const c of rust.categories) assert.ok(universal.includes(c), c);
  });

  it("knows the monthly forced update calendar (first Thursday, 18:00 UTC in summer time, 19:00 UTC otherwise)", () => {
    assert.equal(nextRustForcedUpdate(new Date("2026-10-08T12:00:00Z")).toISOString(), "2026-11-05T19:00:00.000Z");
    assert.equal(nextRustForcedUpdate(new Date("2026-09-01T00:00:00Z")).toISOString(), "2026-09-03T18:00:00.000Z");
    assert.equal(nextRustForcedUpdate(new Date("2026-10-01T18:30:00Z")).toISOString(), "2026-11-05T19:00:00.000Z");
    assert.equal(nextRustForcedUpdate(new Date("2026-12-04T00:00:00Z")).toISOString(), "2027-01-07T19:00:00.000Z");
  });

  it("hook list covers the framework lifecycle and the hooks Cyrus uses", () => {
    for (const h of ["Init", "OnServerInitialized", "Unload", "OnServerSave", "OnPlayerConnected", "OnEntityTakeDamage", "OnPlayerInput", "OnLootSpawn", "OnNpcTarget", "CanMountEntity"]) assert.ok(RUST_HOOK_NAMES.has(h), h);
    assert.ok(!RUST_HOOK_NAMES.has("OnComposterUpdate"), "removed in 2633");
    assert.ok(RUST_HOOK_NAMES.size > 700);
  });
});

describe("Rust generator output", () => {
  const all = projects();

  it(`passes the validator with no blocks and no warnings (${all.length} projects)`, () => {
    for (const p of all) {
      const v = validateRustProject(p.files);
      const bad = v.findings.filter((f) => f.severity !== "info");
      assert.deepEqual(bad, [], `${p.label}: ${JSON.stringify(bad, null, 1)}`);
      assert.ok(v.ok, p.label);
    }
  });

  it("lays files out the way Oxide expects and ships a manifest with the target build", () => {
    for (const p of all) {
      const main = p.files.find((f) => f.path.endsWith(".cs") && !f.path.startsWith("tests/"))!;
      assert.match(main.path, /^oxide\/plugins\/[A-Z]\w*\.cs$/, p.label);
      const mf = p.files.find((f) => f.path === "cyrus.mod.json");
      assert.ok(mf, `${p.label}: manifest`);
      const m = JSON.parse(mf!.content);
      assert.equal(m.targetGameVersion, RUST_CURRENT_VERSION);
      assert.equal(m.side, "server");
      assert.equal(m.clientInstall, false);
      assert.equal(m.entry, main.path);
      assert.equal(m.serverListing, "modded");
      assert.match(m.version, /^\d+\.0\.0$/);
      for (const h of m.hooks) assert.ok(RUST_HOOK_NAMES.has(h), `${p.label}: ${h}`);
      for (const perm of m.permissions) assert.ok(perm.startsWith(m.pluginClass.toLowerCase() + "."), perm);
      for (const f of p.files.filter((x) => x.path.startsWith("oxide/"))) assert.ok(Object.keys(m.install).includes(f.path), `${p.label}: ${f.path} not in manifest`);
      assert.ok(main.content.includes(`Targets Rust ${RUST_CURRENT_VERSION}`));
    }
  });

  it("only emits verified prefab paths", () => {
    for (const p of all) {
      for (const f of p.files) {
        for (const m of f.content.matchAll(/"(assets\/[^"]+\.prefab)"/g)) assert.ok(VERIFIED_PREFABS.has(m[1]), `${p.label} ${f.path}: ${m[1]}`);
      }
    }
  });

  it("never emits an unverified or known-broken API", () => {
    for (const p of all) for (const f of p.files) for (const re of BANNED) assert.ok(!re.test(f.content), `${p.label} ${f.path}: ${re}`);
  });

  it("renames plugin classes that would shadow a game type", () => {
    const files = buildModFiles({ game: RUST, category: CATEGORIES[0], modName: "Item", prompt: "item", model: "saka", version: 1 });
    assert.ok(files.some((f) => f.path === "oxide/plugins/ItemPlugin.cs"));
  });

  it("generated config JSON keys match the C# JsonProperty names", () => {
    for (const p of all) {
      const main = p.files.find((f) => f.path.startsWith("oxide/plugins/"))!;
      const cfg = p.files.find((f) => f.path.startsWith("oxide/config/"));
      if (!cfg) continue;
      const props = [...main.content.matchAll(/\[JsonProperty\("((?:[^"\\]|\\.)*)"\)\]/g)].map((m) => JSON.parse(`"${m[1]}"`));
      assert.deepEqual(Object.keys(JSON.parse(cfg.content)), props, p.label);
    }
  });
});

describe("Rust validator", () => {
  const plugin = (body: string, name = "Demo", extra = "") => `using System;
using Oxide.Core;

namespace Oxide.Plugins
{
    [Info("Demo", "Cyrus", "1.0.0")]
    public class ${name} : RustPlugin
    {
        private const string PermUse = "demo.use";
        private void Init() => permission.RegisterPermission(PermUse, this);
        ${body}
    }
}${extra}`;
  const rules = (src: string, path = "oxide/plugins/Demo.cs") => validateRustSource(path, src).findings.map((f) => `${f.severity}:${f.rule}`);
  const manifest = (o: Record<string, unknown> = {}) => ({
    path: "cyrus.mod.json",
    content: JSON.stringify({ schema: "cyrus.mod/1", game: "rust", name: "Demo", pluginClass: "Demo", version: "1.0.0", targetGameVersion: RUST_CURRENT_VERSION, side: "server", entry: "oxide/plugins/Demo.cs", loaders: { oxide: ">=2.0.7783" }, install: { "oxide/plugins/Demo.cs": "oxide/plugins/Demo.cs" }, ...o }),
  });

  it("accepts a minimal clean plugin", () => {
    assert.deepEqual(rules(plugin("private void OnServerInitialized() => Puts(\"hi\");")), []);
    const v = validateRustProject([{ path: "oxide/plugins/Demo.cs", content: plugin("") }, manifest()]);
    assert.ok(v.ok, JSON.stringify(v.findings));
    assert.equal(v.entry?.className, "Demo");
  });

  it("blocks file, network, process, reflection, native, harmony and thread access", () => {
    const cases: [string, string][] = [
      ['private void A() { System.IO.File.Delete("x"); }', "danger:block"],
      ['private void A() { File.ReadAllText("x"); }', "danger:block"],
      ['private void A() { new WebClient(); }', "danger:block"],
      ['private void A() { webrequest.Enqueue("http://x", null, (c, r) => {}, this); }', "danger:block"],
      ['private void A() { Process.Start("sh"); }', "danger:block"],
      ['private void A() { typeof(BasePlayer).GetMethod("X"); }', "danger:block"],
      ['[DllImport("libc")] private static extern int getpid();', "danger:block"],
      ['private void A() { new Harmony("x").PatchAll(); }', "danger:block"],
      ['private void A() { Thread.Sleep(100); }', "danger:block"],
      ['private void A() { Environment.Exit(0); }', "danger:block"],
      ['private void A() { ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), "quit"); }', "danger:block"],
      ['private void A() { ServerUsers.Set(1UL, ServerUsers.UserGroup.Owner, "", ""); }', "danger:block"],
    ];
    for (const [body, rule] of cases) assert.ok(rules(plugin(body)).includes(`block:${rule}`), body);
  });

  it("allows weather convars and the plugin's own data folder", () => {
    const body = 'private void A() { ConsoleSystem.Run(ConsoleSystem.Option.Server.Quiet(), "weather.fog", -1f); Interface.Oxide.DataFileSystem.WriteObject($"{Name}/Data", 1); }\nprivate void Unload() => A();';
    assert.deepEqual(rules(plugin(body)), []);
  });

  it("ignores dangerous words inside comments and reads TerrainMeta.Path as game API", () => {
    assert.deepEqual(rules(plugin("// File.Delete(x) would be bad\n/* new WebClient() */ private void OnServerInitialized() { var m = TerrainMeta.Path.Monuments; }")), []);
  });

  it("flags structure problems", () => {
    assert.ok(rules(plugin(""), "oxide/plugins/Other.cs").includes("block:structure-filename"));
    assert.ok(rules(plugin("").replace('[Info("Demo", "Cyrus", "1.0.0")]', "")).includes("block:structure-info"));
    assert.ok(rules(plugin("").replace('"1.0.0"', '"v1"')).includes("block:version-format"));
    assert.ok(rules(plugin("").replace("namespace Oxide.Plugins", "namespace Mine")).includes("block:structure-namespace"));
    assert.ok(rules(plugin("private void A() {")).includes("block:syntax-braces"));
    assert.ok(rules(plugin('[ChatCommand("x")] private void A(BasePlayer p, string c, string[] a) {}\n[ChatCommand("x")] private void B(BasePlayer p, string c, string[] a) {}')).includes("block:command-duplicate"));
  });

  it("warns on unknown hooks, foreign permissions, foreign data files, missing cleanup and version pitfalls", () => {
    assert.ok(rules(plugin("private void OnPlayerJumpedTwice(BasePlayer p) {}")).includes("warn:hook-unknown"));
    assert.ok(!rules(plugin("private void OnServerInitialized() {}")).includes("warn:hook-unknown"));
    assert.ok(rules(plugin('private void Loaded() => permission.RegisterPermission("vip.fly", this);')).includes("warn:permission-prefix"));
    assert.ok(rules(plugin('private void A() => Interface.Oxide.DataFileSystem.WriteObject("Economics", 1);')).includes("warn:data-folder"));
    assert.ok(rules(plugin('private void A() { GameManager.server.CreateEntity("x").Spawn(); }')).includes("warn:cleanup-entities"));
    assert.ok(rules(plugin("private void A() { Friends.Call<bool>(\"AreFriends\", 1, 2); }")).includes("warn:version:call-generic-null"));
    assert.ok(rules(plugin("private void OnComposterUpdate(Composter c) {}")).includes("warn:version:removed-hook-composter"));
    assert.ok(rules(plugin('private void A() { var s = "assets/rust.ai/agents/wolf/wolf.prefab"; }')).includes("warn:version:old-wolf-prefab"));
    assert.ok(rules(plugin("private void A(ItemContainer c, Item i) { c.Insert(i); }")).includes("warn:version:container-insert-2634"));
    assert.ok(rules(plugin('private void A() { var s = "../../server.cfg"; }')).includes("block:path-traversal"));
  });

  it("checks the manifest", () => {
    const src = { path: "oxide/plugins/Demo.cs", content: plugin("") };
    assert.ok(validateRustProject([src]).findings.some((f) => f.rule === "manifest-missing"));
    const bad = (o: Record<string, unknown>, rule: string) => assert.ok(validateRustProject([src, manifest(o)]).findings.some((f) => f.rule === rule), rule);
    bad({ side: "both" }, "manifest-side");
    bad({ version: "1.0" }, "version-format");
    bad({ targetGameVersion: "2633.288.1" }, "version-outdated");
    bad({ targetGameVersion: "9999.1.1" }, "version-unknown");
    bad({ entry: "oxide/plugins/Nope.cs" }, "manifest-entry");
    bad({ install: { "a.cs": "../../etc/passwd" } }, "manifest-install");
    bad({ game: "valheim" }, "manifest-field");
  });

  it("strips comments without touching strings and keeps line numbers", () => {
    const src = 'var a = "// not a comment"; // gone\n/* x\ny */ var b = @"a""b";';
    const out = stripCSharp(src);
    assert.ok(out.includes('"// not a comment"'));
    assert.ok(!out.includes("gone"));
    assert.equal(out.split("\n").length, src.split("\n").length);
    assert.ok(stripCSharp(src, true).includes('@"    "'));
  });
});

