// rust-check: compile Cyrus-generated Rust plugins with Roslyn and report diagnostics as JSON lines.
//
//   dotnet run -- [--stubs <dir>] [--refs <dllDir> ...] <plugin-dir-or-file> ...
//
// Each argument that is a directory is one "project": every .cs in it is compiled together (plugin + self-test).
// With --stubs (default ./stubs) the stub sources are added to each compilation; with --refs the DLLs in those
// folders are referenced instead (the owner's RustDedicated_Data/Managed + Oxide release, never committed).
// Exit code 0 = every project compiled without errors.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

static class Program
{
    static int Main(string[] args)
    {
        var stubsDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "stubs");
        var refDirs = new List<string>();
        var targets = new List<string>();
        for (var i = 0; i < args.Length; i++)
        {
            if (args[i] == "--stubs") stubsDir = args[++i];
            else if (args[i] == "--refs") refDirs.Add(args[++i]);
            else targets.Add(args[i]);
        }

        var parse = new CSharpParseOptions(LanguageVersion.CSharp12);
        var refs = new List<MetadataReference>();
        var tpa = ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")).Split(Path.PathSeparator);
        foreach (var p in tpa) refs.Add(MetadataReference.CreateFromFile(p));
        var stubTrees = new List<SyntaxTree>();
        if (refDirs.Count > 0)
        {
            foreach (var dir in refDirs)
                foreach (var dll in Directory.GetFiles(dir, "*.dll"))
                {
                    var name = Path.GetFileName(dll);
                    // the BCL comes from the runtime; game folders also ship mscorlib/netstandard facades
                    if (name.StartsWith("System.") || name == "mscorlib.dll" || name == "netstandard.dll") continue;
                    try { refs.Add(MetadataReference.CreateFromFile(dll)); } catch { /* native dll */ }
                }
        }
        else
        {
            foreach (var f in Directory.GetFiles(stubsDir, "*.cs"))
                stubTrees.Add(CSharpSyntaxTree.ParseText(File.ReadAllText(f), parse, f));
        }

        var failed = 0;
        var total = 0;
        foreach (var target in targets.SelectMany(Expand))
        {
            total++;
            var files = Directory.Exists(target) ? Directory.GetFiles(target, "*.cs") : new[] { target };
            var trees = files.Select(f => CSharpSyntaxTree.ParseText(File.ReadAllText(f), parse, f)).ToList();
            var compilation = CSharpCompilation.Create(
                "Cyrus_" + Path.GetFileName(target.TrimEnd('/')),
