// Sample weapons yakko 0: weapons plugin for Rust, forged by Cyrus (Yakko) v1.
// Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
// Targets Rust 2634.289.1 (October 2026 update), Oxide 2.0.7783+ or Carbon production 2.0.262+. Server-only: players install nothing.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Oxide.Core;
using Rust;
using UnityEngine;
using Random = UnityEngine.Random;

namespace Oxide.Plugins
{
    [Info("Sample weapons yakko 0", "Cyrus", "1.0.0")]
    [Description("A skinned rifle.ak that freezes and slows what it hits")]
    public class SampleWeaponsYakko0 : RustPlugin
    {
        #region Fields

        private const string PermUse = "sampleweaponsyakko0.use";
        private const string PermAdmin = "sampleweaponsyakko0.admin";
        private const string FxHeadshot = "assets/bundled/prefabs/fx/headshot.prefab";

        private Configuration config;
        private readonly Dictionary<ulong, float> cooldowns = new Dictionary<ulong, float>();
        private bool applying;

        #endregion

        #region Oxide Hooks

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            permission.RegisterPermission(PermAdmin, this);
        }

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            var attacker = info?.InitiatorPlayer;
            if (attacker == null || entity == null || !IsCustom(info.Weapon?.GetItem()) || !permission.UserHasPermission(attacker.UserIDString, PermUse)) return null;
            info.damageTypes.ScaleAll(config.DamageMultiplier);
            if (info.isHeadshot) EffectNetwork.Send(new Effect(FxHeadshot, attacker, 0, Vector3.zero, Vector3.zero), attacker.net.connection);
            if (Random.value <= config.ProcChance && !OnCooldown(attacker)) ApplyEffects(attacker, entity, info);
            return null;
        }

        private void OnLootSpawn(LootContainer container)
        {
            if (container == null || !config.LootContainers.Contains(container.ShortPrefabName) || Random.value > config.LootChance) return;
            NextTick(() =>
            {
                if (container == null || container.IsDestroyed || container.inventory == null) return;
                if (container.inventory.itemList.Count >= container.inventory.capacity) container.inventory.capacity++;
                CreateItem()?.MoveToContainer(container.inventory);
            });
        }

        private void OnActiveItemChanged(BasePlayer player, Item oldItem, Item newItem)
        {
            if (player != null && IsCustom(newItem) && permission.UserHasPermission(player.UserIDString, PermUse)) Reply(player, "Equipped", config.DisplayName);
        }

        #endregion

        #region Commands

        [ChatCommand("yakko0")]
        private void CmdGive(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PermAdmin)) { Reply(player, "NoPermission"); return; }
            var target = args.Length > 0 ? BasePlayer.Find(args[0]) : player;
            if (target == null) { Reply(player, "PlayerNotFound", args[0]); return; }
            var item = CreateItem();
            if (item == null) return;
            target.GiveItem(item);
            Reply(player, "Given", config.DisplayName, target.displayName);
        }

        #endregion

        #region Custom Item

        private Item CreateItem(int amount = 1)
        {
            var item = ItemManager.CreateByName(config.Shortname, amount, config.SkinId);
            if (item == null) PrintError($"Unknown item shortname '{config.Shortname}', check the config");
            else Brand(item);
            return item;
        }

        private void Brand(Item item)
        {
            if (config.SkinId != 0UL) item.skin = config.SkinId;
            item.name = config.DisplayName;
            var held = item.GetHeldEntity();
            if (held != null && config.SkinId != 0UL) { held.skinID = config.SkinId; held.SendNetworkUpdate(); }
            item.MarkDirty();
        }

        // The custom item is a renamed vanilla item (plus your Workshop skin, if you set one), so nothing new ships to players.
        private bool IsCustom(Item item) => item != null && item.info.shortname == config.Shortname && item.name == config.DisplayName && (config.SkinId == 0UL || item.skin == config.SkinId);

        #endregion

        #region Effects

        private void ApplyEffects(BaseCombatEntity attacker, BaseCombatEntity target, HitInfo info = null)
        {
            if (applying || (attacker == null && target == null)) return;
            applying = true;
            try
            {
                var victim = target as BasePlayer;

                // Frost: chill them to the bone; Rust's own cold damage does the rest.
                if (target != null) Damage(target, attacker, info, DamageType.Cold, config.EffectPower);
                // Soaked players freeze faster in Rust's own cold (temperature itself is recomputed every tick, so we don't set it).
                if (victim != null) victim.metabolism.wetness.Add(0.6f);
            }
            finally
            {
                applying = false;
            }
        }

        #endregion

        #region API

        private Item API_CreateItem(int amount = 1) => CreateItem(amount);

        #endregion

        #region Helpers

        private bool OnCooldown(BasePlayer player, bool notify = false)
        {
            float readyAt;
            var now = Time.realtimeSinceStartup;
            if (cooldowns.TryGetValue(player.userID.Get(), out readyAt) && readyAt > now)
            {
                if (notify) Reply(player, "Cooldown", readyAt - now);
                return true;
            }
            cooldowns[player.userID.Get()] = now + config.Cooldown;
            return false;
        }

// Sample mechanics saka 2: mechanics plugin for Rust, forged by Cyrus (Saka) v1.
// Runs on Oxide/uMod and Carbon: drop it into oxide/plugins (or carbon/plugins) and it compiles on load.
// Targets Rust 2634.289.1 (October 2026 update), Oxide 2.0.7783+ or Carbon production 2.0.262+. Server-only: players install nothing.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Oxide.Core;
using Rust;
using UnityEngine;

namespace Oxide.Plugins
{
    [Info("Sample mechanics saka 2", "Cyrus", "1.0.0")]
    [Description("Pings the base owner's team when their base is raided, logs the attacker and raid-blocks building")]
    public class SampleMechanicsSaka2 : RustPlugin
    {
        #region Fields

        private const string PermUse = "samplemechanicssaka2.use";
        private const string FxAlarm = "assets/bundled/prefabs/fx/invite_notice.prefab";

        private Configuration config;
        private StoredData data;
        private readonly Dictionary<ulong, float> lastAlert = new Dictionary<ulong, float>();
        private readonly Dictionary<ulong, float> raidBlocked = new Dictionary<ulong, float>();
        private bool applying;

        #endregion

        #region Oxide Hooks

        private void Init()
        {
            permission.RegisterPermission(PermUse, this);
            data = Interface.Oxide.DataFileSystem.ReadObject<StoredData>(Name) ?? new StoredData();
        }

        private void OnServerSave() => SaveData();

